  "replay.hub.hedgeNote": "После явного выбора хеджа длинная и короткая ноги независимо считают маржу, ликвидацию и защиту. Предпочтительны полные исторические входы; недостающие аппроксимируемые пункты используют явно помеченный HEDGE_HYBRID и никогда не откатываются к одностороннему режиму.",
  "replay.hub.marketInRun": "Инструмент выбирается внутри Run",
  "replay.hub.marketInRunDesc": "Создание не фиксирует инструмент, биржу, тип рынка, базовый интервал или набор данных, но передаёт неизменяемый T0. После входа в пустой Run найдите инструмент; сервер только проверяет, поддерживает ли он это время, затем атомарно создаёт первый MarketTrack.",
  "replay.hub.hedgeBind": "HEDGE предпочитает полные исторические входы; отсутствие маркировки/правил/комиссий/ставки финансирования может дать версионированный гибридный вход с раскрытием понижения по пунктам. Непрерывный исторический L2 остаётся жёстким условием только при явном выборе режима с книгой заявок.",
